<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Booking invoice — {{ $order->reference }}</title>
<style>body{margin:0;background:#f4f6f8;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:650px;margin:30px auto;background:#fff}.head{background:#2498e8;color:#fff;padding:32px}.body{padding:32px}.box{background:#f7fafc;border:1px solid #e4e8ee;padding:20px;margin:20px 0}.pay{display:inline-block;background:#f58220;color:#fff;padding:14px 22px;border-radius:6px;text-decoration:none;font-weight:bold}table{width:100%;border-collapse:collapse}td{padding:9px 0;border-bottom:1px solid #eee}td:last-child{text-align:right;font-weight:bold}.muted{color:#64748b}</style></head><body><div class="wrap"><div class="head"><h1 style="margin:0">BOOKING INVOICE</h1><p style="margin:8px 0 0">Karossy Travels &amp; Tours</p></div><div class="body"><p>Dear {{ data_get($order->customer, 'name', 'Traveller') }},</p><p>Your flight has been reserved on hold. Please complete payment before <strong>{{ $order->payment_due_at?->format('D, d M Y H:i') }}</strong>.</p><div class="box"><table><tr><td>Booking reference</td><td>{{ $order->reference }}</td></tr><tr><td>Airline PNR</td><td>{{ $booking->provider_locator }}</td></tr><tr><td>Status</td><td>Pending payment</td></tr><tr><td>Total due</td><td>{{ \App\Support\CurrencyMetadata::format((int) $order->total_minor, $order->currency) }}</td></tr></table></div><h3>Bank transfer details</h3><p><strong>Bank:</strong> {{ $settings->bank_name ?: 'Contact support' }}<br><strong>Account name:</strong> {{ $settings->account_name ?: 'Contact support' }}<br><strong>Account number:</strong> {{ $settings->account_number ?: 'Contact support' }}@if($settings->sort_code)<br><strong>Sort code:</strong> {{ $settings->sort_code }}@endif</p><p class="muted">Use your booking reference as the transfer narration.</p><p><a class="pay" href="{{ $paymentUrl }}">Make payment online</a></p><p class="muted">This is an invoice, not a receipt. A payment receipt will be sent after successful online payment.</p></div></div></body></html>
